function close(a, b) {
  if (!isFinite(a) || !isFinite(b)) return false;
  if (a === b) return true;
  const diff = Math.abs(a - b);
  const scale = Math.max(Math.abs(a), Math.abs(b));
  return diff / scale <= 1e-9;
}

