const { Duration } = require("/luxon/src/luxon.js");

const units = ["years","quarters","months","weeks","days","hours","minutes","seconds","milliseconds"];

function close(a, b) {
  if (a === b) return true;
  if (!isFinite(a) || !isFinite(b)) return false;
  const diff = Math.abs(a - b);
  const scale = Math.max(Math.abs(a), Math.abs(b));
  return diff <= 1e-9 * scale;
}

function runLoop(accuracy) {
  let failures = 0;
  for (const a of units) {
    for (const b of units) {
      const obj = { [a]: 1, [b]: 1 };
      if (accuracy) obj.conversionAccuracy = accuracy;
      const d = Duration.fromObject(obj);
      const before = d.as("milliseconds");
      let n;
      try {
        n = d.normalize();
      } catch (e) {
        console.log(`FAIL (${accuracy || "casual"}) ${a}/${b}: threw ${e && e.message}`);
        failures++;
        continue;
      }
      const o = n.toObject();
      const badVals = Object.entries(o).filter(([, v]) => !isFinite(v));
      const after = n.as("milliseconds");
      if (badVals.length > 0 || !close(after, before)) {
        failures++;
        console.log(
          `FAIL (${accuracy || "casual"}) ${a}/${b}: toObject=${JSON.stringify(o)}` +
            ` nonFinite=${JSON.stringify(badVals)} before=${before} after=${after}`
        );
      }
    }
  }
  return failures;
}

const f1 = runLoop(null);
console.log("casual failure count:", f1);
const f2 = runLoop("longterm");
console.log("longterm failure count:", f2);

console.log("years1+quarters1 normalize casual:", JSON.stringify(Duration.fromObject({ years: 1, quarters: 1 }).normalize().toObject()));
console.log("years1 as quarters (expect 4):", Duration.fromObject({ years: 1 }).as("quarters"));
console.log("quarters1 as years (expect 0.25):", Duration.fromObject({ quarters: 1 }).as("years"));
console.log("years1+quarters1 normalize longterm:", JSON.stringify(Duration.fromObject({ years: 1, quarters: 1, conversionAccuracy: "longterm" }).normalize()
